def test_offset_node_unknown_type_no_crash():
    """_offset_node with an unknown type must not crash -- it silently
    does nothing (no coordinates to offset)."""
    node = {"type": "sparkline", "data": [1, 2, 3]}
    _offset_node(node, 10.0, 20.0)
    # No crash; node unchanged
    assert node == {"type": "sparkline", "data": [1, 2, 3]}


