# ===========================================================================


def test_offset_node_zero_offset_is_noop():
    """_offset_node with dx=0 and dy=0 must return immediately without
    modifying the node."""
    node = {"type": "circle", "cx": 10.0, "cy": 20.0, "r": 5.0, "style": {}}
    _offset_node(node, 0.0, 0.0)
    assert node["cx"] == 10.0
    assert node["cy"] == 20.0


# ===========================================================================
# 7. _offset_node: path with arc_to command
# ===========================================================================


def test_offset_node_path_arc_to():
    """_offset_node must offset arc_to endpoint (x, y) but NOT rx/ry
    (they are radii, not coordinates)."""
    node = {
        "type": "path",
        "commands": [
            {"op": "move_to", "x": 10.0, "y": 20.0},
            {
                "op": "arc_to",
                "rx": 25.0,
                "ry": 25.0,
                "rotation": 0.0,
                "large_arc": False,
                "sweep": True,
                "x": 50.0,
                "y": 60.0,
            },
        ],
    }
    _offset_node(node, 100.0, 200.0)
    arc_cmd = node["commands"][1]
    # Endpoint must be offset
    assert arc_cmd["x"] == 150.0, f"arc_to x not offset: {arc_cmd['x']}"
    assert arc_cmd["y"] == 260.0, f"arc_to y not offset: {arc_cmd['y']}"
    # Radii must NOT be offset
    assert arc_cmd["rx"] == 25.0, f"arc_to rx should not be offset: {arc_cmd['rx']}"
    assert arc_cmd["ry"] == 25.0, f"arc_to ry should not be offset: {arc_cmd['ry']}"


