def test_merge_child_scenes_zero_children():
    """_merge_child_scenes with an empty charts list must return a valid
    empty scene JSON with no panels."""
    scene_json, packed = _merge_child_scenes([], spacing=10.0, layout="horizontal")
    scene = json.loads(scene_json)
    assert scene["panels"] == []
    assert scene["width"] == 0
    assert scene["height"] == 0
    assert packed == b""


