# 9. _merge_child_scenes: 1 child
# ===========================================================================


def test_merge_child_scenes_single_child():
    """_merge_child_scenes with exactly 1 chart must produce 1 panel
    with panel ID 0 and no offset applied."""
    chart = _simple_chart()
    scene_json, packed = _merge_child_scenes([chart], spacing=10.0, layout="horizontal")
    scene = json.loads(scene_json)
    assert len(scene["panels"]) == 1
    assert scene["panels"][0]["id"] == 0
    assert isinstance(packed, bytes)


# ===========================================================================
# 10. _merge_child_scenes_grid: columns=1 (single column)
# ===========================================================================


def test_merge_child_scenes_grid_single_column():
    """_merge_child_scenes_grid with columns=1 must stack all charts vertically."""
    charts = [_simple_chart() for _ in range(3)]
    scene_json, packed = _merge_child_scenes_grid(charts, spacing=10.0, columns=1)
    scene = json.loads(scene_json)
    panels = scene["panels"]
    assert len(panels) == 3
    # Each panel should be in a different row (increasing y)
    y_coords = [p["plot_area"]["y"] for p in panels]
    assert y_coords[1] > y_coords[0], "second panel must be below first"
    assert y_coords[2] > y_coords[1], "third panel must be below second"
    # All in the same column (same x)
    x_coords = [p["plot_area"]["x"] for p in panels]
    assert x_coords[0] == x_coords[1] == x_coords[2], "all panels must have same x offset"


# ===========================================================================
# 11. _merge_child_scenes_grid: columns > len(charts)
# ===========================================================================


def test_merge_child_scenes_grid_columns_exceeds_count():
    """_merge_child_scenes_grid with columns > len(charts) must place all
    charts in a single row."""
    charts = [_simple_chart() for _ in range(2)]
    scene_json, packed = _merge_child_scenes_grid(charts, spacing=10.0, columns=10)
    scene = json.loads(scene_json)
    panels = scene["panels"]
    assert len(panels) == 2
    # Both panels should have the same y (single row)
    y0 = panels[0]["plot_area"]["y"]
    y1 = panels[1]["plot_area"]["y"]
    assert y0 == y1, f"panels should be in same row but y0={y0}, y1={y1}"
    # Panel 1 to the right of panel 0
    assert panels[1]["plot_area"]["x"] > panels[0]["plot_area"]["x"]


