# ===========================================================================
# 18. _background_css_from_dict: malformed background dict (W7)
# ===========================================================================


def test_background_css_from_dict_malformed_raises():  # BUG: _background_css_from_dict crashes on malformed dict -- no try/except guard
    """_background_css_from_dict with a malformed background dict (missing keys)
    should not crash. It should either handle gracefully or the caller should
    guard with try/except."""
    # A background dict missing the 'r' key
    malformed = {"background": {"g": 128, "b": 255, "a": 255}}
    try:
        result = _background_css_from_dict(malformed)
        # If it doesn't crash, any fallback is acceptable
        assert isinstance(result, str)
    except KeyError:
        pytest.fail(
            "_background_css_from_dict crashed with KeyError on malformed background dict; "
            "expected graceful fallback or caller guard"
        )


# ===========================================================================
# 19. _empty_scene: all required keys present
# ===========================================================================


def test_empty_scene_has_all_required_keys():
    """_empty_scene must return a dict with all keys required by the WASM
    SceneGraph deserializer."""
    scene = _empty_scene()
    required_top = {
        "width",
        "height",
        "background",
        "title",
        "panels",
        "legend",
        "decorations",
        "selections",
        "interaction",
    }
    for key in required_top:
        assert key in scene, f"_empty_scene missing top-level key: {key!r}"

    interaction = scene["interaction"]
    required_interaction = {
        "zoom_enabled",
        "pan_enabled",
        "conditionals",
        "linked_panels",
        "tick_levels",
    }
    for key in required_interaction:
        assert key in interaction, f"_empty_scene.interaction missing key: {key!r}"

    # Verify types
    assert isinstance(scene["panels"], list)
    assert isinstance(scene["title"], list)
    assert isinstance(scene["legend"], list)
    assert isinstance(scene["decorations"], list)
    assert isinstance(scene["selections"], list)
    assert isinstance(interaction["conditionals"], list)
    assert isinstance(interaction["linked_panels"], list)
    assert isinstance(interaction["tick_levels"], list)


