# ===========================================================================
# 24. _merge_scene_panels: panel ID re-indexing with offset
# ===========================================================================


def test_merge_scene_panels_reindexing():
    """_merge_scene_panels must add panel_id_offset to each panel ID."""
    merged = _empty_scene()
    child_scene = {
        "panels": [
            {
                "id": 0,
                "plot_area": {"x": 0, "y": 0, "w": 100, "h": 80},
                "clip": {"x": 0, "y": 0, "w": 100, "h": 80},
                "marks": [],
                "axes": [],
                "grid": [],
                "annotations": [],
            },
            {
                "id": 1,
                "plot_area": {"x": 110, "y": 0, "w": 100, "h": 80},
                "clip": {"x": 110, "y": 0, "w": 100, "h": 80},
                "marks": [],
                "axes": [],
                "grid": [],
                "annotations": [],
            },
        ]
    }
    _merge_scene_panels(merged, child_scene, dx=200.0, dy=50.0, panel_id_offset=5)
    assert len(merged["panels"]) == 2
    assert merged["panels"][0]["id"] == 5
    assert merged["panels"][1]["id"] == 6
    # Plot areas must be offset by dx, dy
    assert merged["panels"][0]["plot_area"]["x"] == 200.0
    assert merged["panels"][0]["plot_area"]["y"] == 50.0
    assert merged["panels"][1]["plot_area"]["x"] == 310.0
    assert merged["panels"][1]["plot_area"]["y"] == 50.0


# ===========================================================================
# 25. _merge_scene_panels does not mutate original scene
# ===========================================================================


def test_merge_scene_panels_does_not_mutate_original():
    """_merge_scene_panels must deep-copy panels before mutation."""
    merged = _empty_scene()
    child_scene = {
        "panels": [
            {
                "id": 0,
                "plot_area": {"x": 10, "y": 20, "w": 100, "h": 80},
                "clip": {"x": 10, "y": 20, "w": 100, "h": 80},
                "marks": [],
                "axes": [],
                "grid": [],
                "annotations": [],
            }
        ]
    }
    original_x = child_scene["panels"][0]["plot_area"]["x"]
    _merge_scene_panels(merged, child_scene, dx=50.0, dy=30.0, panel_id_offset=0)
    # Original scene must not be mutated
    assert child_scene["panels"][0]["plot_area"]["x"] == original_x, (
        "original scene was mutated by _merge_scene_panels"
    )


