# ===========================================================================
# 29. _offset_node: group with nested mixed types
# ===========================================================================


def test_offset_node_group_recursive():
    """_offset_node on a group must recursively offset all children."""
    node = {
        "type": "group",
        "attrs": [],
        "children": [
            {"type": "circle", "cx": 10.0, "cy": 20.0, "r": 5.0, "style": {}},
            {"type": "rect", "x": 30.0, "y": 40.0, "w": 50.0, "h": 60.0, "style": {}},
            {
                "type": "group",
                "attrs": [],
                "children": [
                    {"type": "text", "x": 100.0, "y": 110.0, "content": "hi", "style": {}},
                ],
            },
        ],
    }
    _offset_node(node, 7.0, 13.0)
    assert node["children"][0]["cx"] == 17.0
    assert node["children"][0]["cy"] == 33.0
    assert node["children"][1]["x"] == 37.0
    assert node["children"][1]["y"] == 53.0
    # Nested group child
    assert node["children"][2]["children"][0]["x"] == 107.0
    assert node["children"][2]["children"][0]["y"] == 123.0


# ===========================================================================
# 30. Composition .save(format="svg") round-trip
# ===========================================================================


def test_composition_save_svg_roundtrip(tmp_path):
    """HConcatChart.save() with SVG format must write valid SVG to disk."""
    composed = HConcatChart([_simple_chart(), _simple_chart()])
    out = tmp_path / "comp.svg"
    composed.save(str(out))
    content = out.read_text()
    assert "<svg" in content
    assert "NaN" not in content


# ===========================================================================
# 31. Composition .save() with unsupported format raises
# ===========================================================================


def test_composition_save_unsupported_format_raises():
    """Saving composition with a genuinely unsupported format raises ValueError."""
    import tempfile
    import os

    composed = HConcatChart([_simple_chart(), _simple_chart()])
    with tempfile.NamedTemporaryFile(suffix=".xyz", delete=False) as f:
        tmp = f.name
    try:
        with pytest.raises(ValueError, match="xyz|not supported"):
            composed.save(tmp, format="xyz")
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def test_composition_save_pdf_works():
    """Saving composition as PDF now succeeds (F14)."""
    import tempfile
    import os

    composed = HConcatChart([_simple_chart(), _simple_chart()])
    with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as f:
        tmp = f.name
    try:
        composed.save(tmp)
        with open(tmp, "rb") as fh:
            assert fh.read(5) == b"%PDF-"
    finally:
        os.unlink(tmp)


